-- =====================================================================
-- 015: Workout-Datenbank aufgeräumt.
-- 1) Umlaute und Zeichen (♂ ♀ ’ …), die beim Import kaputtgegangen sind,
--    in Vorlagen, Terminen und Abstimmungs-Optionen reparieren.
-- 2) Jede Vorlage bekommt feste Tags: Gruppe (Girls, Hero, CrossFit, Hyrox …),
--    Art (For Time, AMRAP, EMOM …) und Geräte (Langhantel, Kettlebell …).
--    Erzeugt mit js/classify.js, von Hand nachgeprüft. Zuordnung über den Titel.
-- Mehrfach ausführbar.
-- =====================================================================

-- 1) Zeichen reparieren
update workout_templates set title = replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(title, '‚ôÄ', '♀'), '‚ôÇ', '♂'), '‚Äô', '’'), '‚Äú', '“'), '‚Äù', '”'), '‚Äî', '—'), '‚Ä≥', '″'), '‚Äì', '–'), '√∂', 'ö'), '¬æ', '¾'), '¬Ω', '½'), '√©', 'é'), workout = replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(workout, '‚ôÄ', '♀'), '‚ôÇ', '♂'), '‚Äô', '’'), '‚Äú', '“'), '‚Äù', '”'), '‚Äî', '—'), '‚Ä≥', '″'), '‚Äì', '–'), '√∂', 'ö'), '¬æ', '¾'), '¬Ω', '½'), '√©', 'é'), notes = replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(notes, '‚ôÄ', '♀'), '‚ôÇ', '♂'), '‚Äô', '’'), '‚Äú', '“'), '‚Äù', '”'), '‚Äî', '—'), '‚Ä≥', '″'), '‚Äì', '–'), '√∂', 'ö'), '¬æ', '¾'), '¬Ω', '½'), '√©', 'é')
 where title ~ '‚ôÄ|‚ôÇ|‚Äô|‚Äú|‚Äù|‚Äî|‚Ä≥|‚Äì|√∂|¬æ|¬Ω|√©' or workout ~ '‚ôÄ|‚ôÇ|‚Äô|‚Äú|‚Äù|‚Äî|‚Ä≥|‚Äì|√∂|¬æ|¬Ω|√©' or notes ~ '‚ôÄ|‚ôÇ|‚Äô|‚Äú|‚Äù|‚Äî|‚Ä≥|‚Äì|√∂|¬æ|¬Ω|√©';

update events set title = replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(title, '‚ôÄ', '♀'), '‚ôÇ', '♂'), '‚Äô', '’'), '‚Äú', '“'), '‚Äù', '”'), '‚Äî', '—'), '‚Ä≥', '″'), '‚Äì', '–'), '√∂', 'ö'), '¬æ', '¾'), '¬Ω', '½'), '√©', 'é'), workout = replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(workout, '‚ôÄ', '♀'), '‚ôÇ', '♂'), '‚Äô', '’'), '‚Äú', '“'), '‚Äù', '”'), '‚Äî', '—'), '‚Ä≥', '″'), '‚Äì', '–'), '√∂', 'ö'), '¬æ', '¾'), '¬Ω', '½'), '√©', 'é'), note = replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(note, '‚ôÄ', '♀'), '‚ôÇ', '♂'), '‚Äô', '’'), '‚Äú', '“'), '‚Äù', '”'), '‚Äî', '—'), '‚Ä≥', '″'), '‚Äì', '–'), '√∂', 'ö'), '¬æ', '¾'), '¬Ω', '½'), '√©', 'é')
 where title ~ '‚ôÄ|‚ôÇ|‚Äô|‚Äú|‚Äù|‚Äî|‚Ä≥|‚Äì|√∂|¬æ|¬Ω|√©' or workout ~ '‚ôÄ|‚ôÇ|‚Äô|‚Äú|‚Äù|‚Äî|‚Ä≥|‚Äì|√∂|¬æ|¬Ω|√©' or note ~ '‚ôÄ|‚ôÇ|‚Äô|‚Äú|‚Äù|‚Äî|‚Ä≥|‚Äì|√∂|¬æ|¬Ω|√©';

update workout_options set label = replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(label, '‚ôÄ', '♀'), '‚ôÇ', '♂'), '‚Äô', '’'), '‚Äú', '“'), '‚Äù', '”'), '‚Äî', '—'), '‚Ä≥', '″'), '‚Äì', '–'), '√∂', 'ö'), '¬æ', '¾'), '¬Ω', '½'), '√©', 'é'), workout = replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(workout, '‚ôÄ', '♀'), '‚ôÇ', '♂'), '‚Äô', '’'), '‚Äú', '“'), '‚Äù', '”'), '‚Äî', '—'), '‚Ä≥', '″'), '‚Äì', '–'), '√∂', 'ö'), '¬æ', '¾'), '¬Ω', '½'), '√©', 'é')
 where label ~ '‚ôÄ|‚ôÇ|‚Äô|‚Äú|‚Äù|‚Äî|‚Ä≥|‚Äì|√∂|¬æ|¬Ω|√©' or workout ~ '‚ôÄ|‚ôÇ|‚Äô|‚Äú|‚Äù|‚Äî|‚Ä≥|‚Äì|√∂|¬æ|¬Ω|√©';

